#include "stdafx.h"#include "ListValue.h"#ifdef _MANAGED#pragma managed(push, off)#endifHANDLE GiveSem( const char* name ){  char szSem[32];  sprintf_s( szSem, sizeof(szSem), "HONEYWELL_QB_Sem_%s", name );  HANDLE hSem = ::OpenSemaphore( SEMAPHORE_ALL_ACCESS, FALSE, szSem );  if( hSem == NULL )    hSem = ::CreateSemaphore( NULL, 1, 1, szSem );  return hSem;}//HANDLE hSemValue = NULL;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					            ){  switch ( ul_reason_for_call )  {  case DLL_PROCESS_ATTACH:    {      hSemValue = GiveSem( "Value" );      HMODULE hU = GetModuleHandle("UtilsQB5xx.dll");      theList.Attach(hU);    }    break;  case DLL_PROCESS_DETACH:    {      theList.Detach();    }    break;  };  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endif